import org.junit.jupiter.api.Test;

/**
 * A pipeline plan cache waiter parked on another request's flight stops waiting at once when its own request is
 * cancelled (connection shutdown and query timeout reach the planning thread as an interrupt). It fails like a
 * cancelled planning, with a {@link QueryInterruptedException}; the owner, the other waiters and the cache's flight and
 * byte bookkeeping are unaffected.
 */
class LmdbPipelinePlanCacheCancelledWaiterTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void interruptedWaiterStopsWaitingAtOnceAndLeavesTheFlightToTheOthers() throws Exception {
		Run withInterruptedWaiter = new Run(true);
		Bookkeeping cancelled = withInterruptedWaiter.execute();
		Run withoutIt = new Run(false);
		Bookkeeping baseline = withoutIt.execute();

		assertEquals(baseline, cancelled, "the interrupted waiter leaves no trace in the cache's bookkeeping");
		// Per-request counters: the interrupted request's own decision-cache miss and its own park on the flight.
		assertEquals(withoutIt.replans + 1L, withInterruptedWaiter.replans, "its own lookup miss is counted");
		assertEquals(withoutIt.waits + 1L, withInterruptedWaiter.waits, "its own park is counted");
	}

	/**
	 * Cache bookkeeping that a waiter could disturb: retained families, aliases and bytes, in-flight byte reservations
	 * (what {@code abandon} releases), publications, evictions and lookup hits.
	 */
	private record Bookkeeping(int entries, long retainedBytes, long reservedFlightBytes, long families,
			long exactAliases, long publications, long stalePublications, long evictions, long hits) {

		static Bookkeeping of(LmdbPipelinePlanCache cache) {
			LmdbPlanDecisionCache.Statistics statistics = cache.decisionCacheForTest().statistics();
			return new Bookkeeping(cache.entryCount(), cache.retainedBytes(),
					cache.decisionCacheForTest().reservedBytesForTest(), statistics.families(),
					statistics.exactAliases(), statistics.publications(), statistics.stalePublications(),
					statistics.evictions(), cache.hits());
		}
	}

	/**
	 * One owner held inside its planning by a latch; optionally a first waiter that is interrupted while the owner is
	 * still held; then a second waiter; then the owner publishes, and a later request looks the plan up.
	 */
	private static final class Run {
		private final boolean interruptFirstWaiter;
		private final LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		private final LmdbPipelinePlanCache.Context context = context(17L);
		private final AtomicInteger computations = new AtomicInteger();
		private final CountDownLatch ownerEntered = new CountDownLatch(1);
		private final CountDownLatch releaseOwner = new CountDownLatch(1);
		private long waits;
		private long replans;

		Run(boolean interruptFirstWaiter) {
			this.interruptFirstWaiter = interruptFirstWaiter;
		}

		Bookkeeping execute() throws Exception {
			ExecutorService executor = Executors.newFixedThreadPool(2);
			try {
				Future<LmdbPipelinePlanCache.Result> owner = executor.submit(() -> cache.getOrCompute(
						query("_anon_1"), context, context::revision, () -> {
							computations.incrementAndGet();
							ownerEntered.countDown();
							await(releaseOwner);
							return planned(query("_anon_1"));
						}));
				assertTrue(ownerEntered.await(10L, TimeUnit.SECONDS), "fixture: the owner is planning");

				if (interruptFirstWaiter) {
					AtomicReference<Throwable> failure = new AtomicReference<>();
					AtomicBoolean interruptFlagKept = new AtomicBoolean();
					CountDownLatch done = new CountDownLatch(1);
					Thread waiter = new Thread(() -> {
						try {
							cache.getOrCompute(query("_anon_2"), context, context::revision,
									() -> planned(query("_anon_2"), computations));
						} catch (Throwable thrown) {
							failure.set(thrown);
							interruptFlagKept.set(Thread.currentThread().isInterrupted());
						} finally {
							done.countDown();
						}
					});
					waiter.start();
					spinUntil(() -> cache.waits() == 1L, "the first waiter to park on the owner's flight");

					waiter.interrupt();

					assertTrue(done.await(10L, TimeUnit.SECONDS), "the interrupted waiter stops waiting at once");
					assertFalse(owner.isDone(), "fixture: the owner is still held");
					assertInstanceOf(QueryInterruptedException.class, failure.get(),
							() -> "fails like a cancelled planning: " + failure.get());
					assertTrue(interruptFlagKept.get(), "the interrupt status stays set for the request's owner");
				}

				long parkedBefore = cache.waits();
				Future<LmdbPipelinePlanCache.Result> second = executor.submit(() -> cache.getOrCompute(
						query("_anon_3"), context, context::revision, () -> planned(query("_anon_3"), computations)));
				spinUntil(() -> cache.waits() == parkedBefore + 1L, "the second waiter to park on the flight");

				releaseOwner.countDown();
				LmdbPipelinePlanCache.Result owned = owner.get(10L, TimeUnit.SECONDS);
				LmdbPipelinePlanCache.Result waited = second.get(10L, TimeUnit.SECONDS);
				LmdbPipelinePlanCache.Result later = cache.getOrCompute(query("_anon_4"), context, context::revision,
						() -> planned(query("_anon_4"), computations));

				assertFalse(owned.cacheHit(), "the owner computed its plan");
				assertTrue(waited.cacheHit(), "the second waiter receives the owner's plan");
				assertTrue(later.cacheHit(), "a later request finds the owner's published plan");
				assertEquals(1, computations.get(), "only the owner planned");
				waits = cache.waits();
				replans = cache.decisionCacheForTest().statistics().replans();
				return Bookkeeping.of(cache);
			} finally {
				releaseOwner.countDown();
				executor.shutdownNow();
			}
		}
	}

	private static QueryRoot query(String anonymousName) {
		StatementPattern pattern = new StatementPattern(
				Var.of(anonymousName, true), Var.of("predicate", VF.createIRI("urn:left")), Var.of("object"));
		Projection projection = new Projection(pattern, new ProjectionElemList(new ProjectionElem("object")));
		return new QueryRoot(projection);
	}

	private static TupleExpr planned(TupleExpr plan) {
		plan.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		return plan;
	}

	private static TupleExpr planned(TupleExpr plan, AtomicInteger computations) {
		computations.incrementAndGet();
		return planned(plan);
	}

	private static void spinUntil(BooleanSupplier condition, String what) {
		long bound = System.nanoTime() + TimeUnit.SECONDS.toNanos(10L);
		while (!condition.getAsBoolean()) {
			if (System.nanoTime() > bound) {
				fail("timed out waiting for " + what);
			}
			Thread.onSpinWait();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(30L, TimeUnit.SECONDS)) {
				throw new AssertionError("test latch was not released");
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while coordinating cache flight", interrupted);
		}
	}

	private static LmdbPipelinePlanCache.Context context(long dataRevision) {
		LmdbEstimatorRuntime.PlanningRevisions planning = new LmdbEstimatorRuntime.PlanningRevisions(
				dataRevision, 2L, 3L, 4L);
		return new LmdbPipelinePlanCache.Context(
				new LmdbPipelinePlanCache.Revision(planning, true), false, 0L,
				LmdbPipelinePlanCache.DatasetIdentity.of(null), LmdbPipelinePlanCache.BindingIdentity.of(null), "",
				false, false, false, "STANDARD", false);
	}
}
